    /// <summary>
    ///
    /// </summary>
    public static void modifyQuery(MethodName _filterName, Query _query, TFMRequestElement _filters)
    {
        TFMFilterAdditionsDataBinding	dataBinding;
        QueryBuildDataSource			qbds;
        QueryBuildRange					qbr;

        while select dataBinding where dataBinding.FilterName == _filterName
        {
			if (_filters.getFieldValue(dataBinding.FilterFieldName))
            {
                qbds = _query.dataSourceTable(tableName2Id(dataBinding.TableName));
				if (qbds)
                {
                    qbr = qbds.addRange(fieldName2Id(tableName2Id(dataBinding.TableName),dataBinding.FieldName));
                    if (SysTest::hasMethod(_filters, 'parm'+dataBinding.FilterFieldName))
                    {

                        qbr.value(strFmt('%1', new SysDictClass(classIdGet(_filters)).callObject('parm' + dataBinding.FilterFieldName,_filters)));
                    }
					else
                    {
                        qbr.value(_filters.getFieldValue(dataBinding.FilterFieldName));
                    }
                }
            }
        }
    }

/// <summary>
///
/// </summary>
public void insert()
{
    TFMFilterAdditions additions;
    if (!TFMFilterAdditions::exist(this.filterName,this.filterFieldName))
    {
        additions.FilterName = this.filterName;
        additions.FilterFieldName = this.filterFieldName;
        additions.insert();
    }
    super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;
    TFMFilterAdditions additions;
    if (!TFMFilterAdditions::exist(this.filterName,this.filterFieldName))
    {
        additions.FilterName = this.filterName;
        additions.FilterFieldName = this.filterFieldName;
        additions.insert();
    }
    ret = super();

    return ret;
}
